import React from 'react';
import { ConnectionProvider, WalletProvider } from '@solana/wallet-adapter-react';
import { WalletModalProvider, WalletMultiButton } from '@solana/wallet-adapter-react-ui';
import { PhantomWalletAdapter, SolflareWalletAdapter } from '@solana/wallet-adapter-wallets';
import WalletAddress from './components/WalletAddress';
import TransactionTable from './components/TransactionTable';
import { clusterApiUrl } from '@solana/web3.js';

import '@solana/wallet-adapter-react-ui/styles.css';
import './App.css';
import ConnectedWallets from './components/ConnectedWallet';


// Use Solana's public devnet endpoint
const SOLANA_RPC = clusterApiUrl('devnet');


// const QUICKNODE_RPC = 'https://still-proud-river.solana-mainnet.quiknode.pro/996b6cc94785b6265bc1d5f950a2f83e41c0b111';



const App = () => {
    const wallets = [new PhantomWalletAdapter(), new SolflareWalletAdapter()];

    return (
        <ConnectionProvider endpoint={SOLANA_RPC}>
            <WalletProvider wallets={wallets} autoConnect>
                <WalletModalProvider>
                    <div className="app-container">
                        <h1>DevNet Explorer</h1>
                        <WalletMultiButton/>
                        <WalletAddress />
                        <TransactionTable />
                        {/* <ConnectedWallets/> */}
                    </div>
                </WalletModalProvider>
            </WalletProvider>
        </ConnectionProvider>
    );
};

export default App;
