import React, { useState, useEffect } from 'react';
import { useWallet } from '@solana/wallet-adapter-react';
import './TransactionTable.css';

const { Connection, clusterApiUrl, PublicKey } = require('@solana/web3.js');

const TransactionTable = () => {
    const { publicKey } = useWallet();
    const [transactions, setTransactions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (publicKey) {
            const connection = new Connection(clusterApiUrl('devnet'), 'confirmed');

            const fetchTransactions = async () => {
                setLoading(true);
                setError(null);

                try {
                    const signatures = await connection.getSignaturesForAddress(
                        publicKey,
                        { limit: 20 }
                    );
                    
                    const transactionsData = await Promise.all(
                        signatures.map(async (sigInfo) => {
                            const tx = await connection.getParsedTransaction(
                                sigInfo.signature,
                                { commitment: 'confirmed' }
                            );
                            const transfer = await extractTokenTransfer(tx, connection);
                            return {
                                signature: sigInfo.signature,
                                blockTime: tx?.blockTime,
                                transfer: transfer
                            };
                        })
                    );

                    setTransactions(transactionsData);
                } catch (error) {
                    console.error('Error fetching transactions:', error);
                    setError(error.message);
                } finally {
                    setLoading(false);
                }
            };

            fetchTransactions();
        } else {
            // If wallet is disconnected, clear transactions
            setTransactions([]);
        }
    }, [publicKey]); // Re-run this when publicKey changes

    const formatBlockTime = (blockTime) => {
        if (!blockTime) return 'No timestamp';
        const date = new Date(blockTime * 1000);
        return date.toLocaleString();
    };

    const formatSignature = (signature) => {
        if (!signature) return 'No signature';
        return `${signature.slice(0, 4)}...${signature.slice(-4)}`;
    };

    const formatAmount = (amount) => {
        if (typeof amount !== 'number' || isNaN(amount)) return '0';
        return amount.toFixed(4);
    };

    const extractTokenTransfer = async (transaction, connection) => {
        // Check for SOL transfer
        if (transaction?.meta?.preBalances && transaction?.meta?.postBalances) {
            const preBalances = transaction.meta.preBalances;
            const postBalances = transaction.meta.postBalances;
            const accountKeys = transaction.transaction.message.accountKeys;

            let maxChange = 0;
            let solTransfer = null;

            accountKeys.forEach((account, index) => {
                const balanceChange = Math.abs(postBalances[index] - preBalances[index]);
                if (balanceChange > maxChange) {
                    maxChange = balanceChange;
                    solTransfer = {
                        type: 'SOL',
                        amount: balanceChange / 1e9, // Convert from lamports to SOL
                        tokenName: 'SOL'
                    };
                }
            });

            if (solTransfer && solTransfer.amount > 0) {
                return solTransfer;
            }
        }

        // Check for SPL token transfer
        if (transaction?.transaction?.message?.instructions) {
            for (const instruction of transaction.transaction.message.instructions) {
                if (instruction.programId?.toString() === 'TokenkegQfeZyiNwAJbYqS4pP7h5bG9bCSc8k9A4gsLjsZ') {
                    const mintAddress = instruction?.accounts?.[1];
                    const tokenName = await fetchTokenName(mintAddress, connection);
                    const amount = instruction?.parsed?.info?.amount || 0;
                    const decimals = await getTokenDecimals(mintAddress, connection);

                    return {
                        type: 'SPL',
                        amount: amount / (10 ** decimals),
                        tokenName: tokenName
                    };
                }
            }
        }

        return null;
    };

    const fetchTokenName = async (mintAddress, connection) => {
        if (!mintAddress) return 'Unknown Token';
        try {
            const mintPublicKey = new PublicKey(mintAddress);
            const tokenInfo = await connection.getParsedAccountInfo(mintPublicKey);
            return tokenInfo?.value?.data?.parsed?.info?.symbol || 'Unknown Token';
        } catch (error) {
            return 'Unknown Token';
        }
    };

    const getTokenDecimals = async (mintAddress, connection) => {
        try {
            const mintPublicKey = new PublicKey(mintAddress);
            const tokenAccountInfo = await connection.getParsedAccountInfo(mintPublicKey);
            return tokenAccountInfo?.value?.data?.parsed?.info?.decimals || 9;
        } catch (error) {
            return 9;
        }
    };

    return (
        <div className="transaction-table">
            <h2>Transactions ({transactions.length})</h2>

            {loading && <p className="loading">Loading Transactions...</p>}

            {error && <p className="error">Error: {error}</p>}

            {!loading && !error && transactions.length === 0 && !publicKey && (
                <p className='connect'>Connect your wallet to see transactions.</p> // Message when wallet is disconnected
            )}

            {!loading && !error && transactions.length === 0 && publicKey && (
                <p>No transactions found.</p> // Message when there are no transactions but wallet is connected
            )}

            {!loading && !error && transactions.length > 0 && (
                <div className="tbody-wrapper">
                    <table>
                        <thead>
                            <tr>
                                <th>Signature</th>
                                <th>Time</th>
                                <th>Token</th>
                                <th>Amount</th>
                            </tr>
                        </thead>
                        <tbody>
                            {transactions.map((tx, index) => (
                                <tr key={tx.signature || index}>
                                    <td>{formatSignature(tx.signature)}</td>
                                    <td>{formatBlockTime(tx.blockTime)}</td>
                                    <td>{tx.transfer?.type || 'N/A'}</td>
                                    <td>
                                        {tx.transfer ? (
                                            `${formatAmount(tx.transfer.amount)} ${tx.transfer.tokenName}`
                                        ) : (
                                            'N/A'
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default TransactionTable;
